function employee_appraisal_table_insert(&$error_message = '') {
	global $Translation;

	// mm: can member insert record?
	$arrPerm = getTablePermissions('employee_appraisal_table');
	if(!$arrPerm['insert']) {
		$error_message = $Translation['no insert permission'];
		return false;
	}

	// automatic employee_name if passed as filterer
	if(Request::val('filterer_employee_name')) {
		$_REQUEST['employee_name'] = Request::val('filterer_employee_name');
	}

	$data = [
		'designation' => Request::val('designation', ''),
		'reporting_officer' => Request::lookup('reporting_officer', ''),
		'reviewing_officer' => Request::lookup('reviewing_officer', ''),
		'created_by' => parseCode('<%%creatorUsername%%>', true),
		'created_at' => parseCode('<%%creationDateTime%%>', true),
	];


	// automatic employee_name if passed as filterer
	if(Request::val('filterer_employee_name')) {
		$data['employee_name'] = Request::val('filterer_employee_name');
	}
	// record owner is current user
	$recordOwner = getLoggedMemberID();

	$recID = tableInsert('employee_appraisal_table', $data, $recordOwner, $error_message);

	// if this record is a copy of another record, copy children if applicable
	if(strlen(Request::val('SelectedID')) && $recID !== false)
		employee_appraisal_table_copy_children($recID, Request::val('SelectedID'));

	return $recID;
}

function employee_appraisal_table_copy_children($destination_id, $source_id) {
	global $Translation;
	$requests = []; // array of curl handlers for launching insert requests
	$eo = ['silentErrors' => true];
	$safe_sid = makeSafe($source_id);
	$currentUsername = getLoggedMemberID();
	$errorMessage = '';

	// launch requests, asynchronously
	curl_batch($requests);
}

function employee_appraisal_table_delete($selected_id, $AllowDeleteOfParents = false, $skipChecks = false) {
	// insure referential integrity ...
	global $Translation;
	$selected_id = makeSafe($selected_id);

	// mm: can member delete record?
	if(!check_record_permission('employee_appraisal_table', $selected_id, 'delete')) {
		return $Translation['You don\'t have enough permissions to delete this record'];
	}

	// hook: employee_appraisal_table_before_delete
	if(function_exists('employee_appraisal_table_before_delete')) {
		$args = [];
		if(!employee_appraisal_table_before_delete($selected_id, $skipChecks, getMemberInfo(), $args))
			return $Translation['Couldn\'t delete this record'] . (
				!empty($args['error_message']) ?
					'<div class="text-bold">' . strip_tags($args['error_message']) . '</div>'
					: '' 
			);
	}

	sql("DELETE FROM `employee_appraisal_table` WHERE `id`='{$selected_id}'", $eo);

	// hook: employee_appraisal_table_after_delete
	if(function_exists('employee_appraisal_table_after_delete')) {
		$args = [];
		employee_appraisal_table_after_delete($selected_id, getMemberInfo(), $args);
	}

	// mm: delete ownership data
	sql("DELETE FROM `membership_userrecords` WHERE `tableName`='employee_appraisal_table' AND `pkValue`='{$selected_id}'", $eo);
}

function employee_appraisal_table_update(&$selected_id, &$error_message = '') {
	global $Translation;

	// mm: can member edit record?
	if(!check_record_permission('employee_appraisal_table', $selected_id, 'edit')) return false;

	$data = [
		'designation' => Request::val('designation', ''),
		'reporting_officer' => Request::lookup('reporting_officer', ''),
		'reviewing_officer' => Request::lookup('reviewing_officer', ''),
		'last_updated_by' => parseCode('<%%editorUsername%%>', false),
		'last_updated_at' => parseCode('<%%editingDateTime%%>', false),
	];

	// get existing values
	$old_data = getRecord('employee_appraisal_table', $selected_id);
	if(is_array($old_data)) {
		$old_data = array_map('makeSafe', $old_data);
		$old_data['selectedID'] = makeSafe($selected_id);
	}

	$data['selectedID'] = makeSafe($selected_id);

	// hook: employee_appraisal_table_before_update
	if(function_exists('employee_appraisal_table_before_update')) {
		$args = ['old_data' => $old_data];
		if(!employee_appraisal_table_before_update($data, getMemberInfo(), $args)) {
			if(isset($args['error_message'])) $error_message = $args['error_message'];
			return false;
		}
	}

	$set = $data; unset($set['selectedID']);
	foreach ($set as $field => $value) {
		$set[$field] = ($value !== '' && $value !== NULL) ? $value : NULL;
	}

	if(!update(
		'employee_appraisal_table', 
		backtick_keys_once($set), 
		['`id`' => $selected_id], 
		$error_message
	)) {
		echo $error_message;
		echo '<a href="employee_appraisal_table_view.php?SelectedID=' . urlencode($selected_id) . "\">{$Translation['< back']}</a>";
		exit;
	}


	update_calc_fields('employee_appraisal_table', $data['selectedID'], calculated_fields()['employee_appraisal_table']);

	// hook: employee_appraisal_table_after_update
	if(function_exists('employee_appraisal_table_after_update')) {
		if($row = getRecord('employee_appraisal_table', $data['selectedID'])) $data = array_map('makeSafe', $row);

		$data['selectedID'] = $data['id'];
		$args = ['old_data' => $old_data];
		if(!employee_appraisal_table_after_update($data, getMemberInfo(), $args)) return;
	}

	// mm: update record update timestamp
	set_record_owner('employee_appraisal_table', $selected_id);
}

